import { beforeEach, expect, it, vi } from "vitest";

const mocks = vi.hoisted(() => ({
  handlers: new Map<string, (context: unknown) => Promise<unknown>>(),
  users: vi.fn(),
  jobs: vi.fn(),
  prepare: vi.fn(),
  expire: vi.fn(),
  process: vi.fn(),
}));
vi.mock("@/lib/inngest-client", () => ({
  inngest: {
    createFunction: (
      opts: { id: string },
      handler: (context: unknown) => Promise<unknown>,
    ) => {
      mocks.handlers.set(opts.id, handler);
      return { opts };
    },
  },
}));
vi.mock("@/lib/db", () => ({
  db: {
    user: { findMany: mocks.users },
    accountDeletionJob: { findMany: mocks.jobs },
  },
}));
vi.mock("@/lib/deletion-jobs", () => ({
  expireDeletionCredentials: mocks.expire,
  prepareDeletionJob: mocks.prepare,
  runDeletionJob: mocks.process,
}));
import { deletionJobSweep } from "@/lib/lifecycle-jobs";

beforeEach(() => {
  vi.clearAllMocks();
  mocks.users.mockResolvedValue([]);
  mocks.jobs.mockResolvedValue([]);
});
const run = async (_id: string, work: () => unknown) => work();

it("schedules deletion once daily at 02:00 UTC with three idle steps and no events", async () => {
  expect(deletionJobSweep.opts).toMatchObject({
    triggers: { cron: "0 2 * * *" },
    concurrency: 1,
  });
  const stepRun = vi.fn(run),
    sendEvent = vi.fn();
  await mocks.handlers.get("account-deletion-jobs")!({
    step: { run: stepRun, sendEvent },
  });
  expect(mocks.expire).toHaveBeenCalledOnce();
  expect(stepRun).toHaveBeenCalledTimes(3);
  expect(sendEvent).not.toHaveBeenCalled();
});

it("prepares legacy requests before scanning due jobs and dispatches each owner once", async () => {
  const userId = "11111111-1111-4111-8111-111111111111";
  mocks.users.mockResolvedValue([{ id: userId }]);
  mocks.jobs.mockResolvedValue([{ id: "job", userId }]);
  const sendEvent = vi.fn();
  await mocks.handlers.get("account-deletion-jobs")!({
    step: { run, sendEvent },
  });
  expect(mocks.prepare).toHaveBeenCalledExactlyOnceWith(userId);
  expect(mocks.prepare.mock.invocationCallOrder[0]).toBeLessThan(
    mocks.jobs.mock.invocationCallOrder[0],
  );
  expect(sendEvent).toHaveBeenCalledExactlyOnceWith("dispatch-0", [
    { name: "mailloop/account.deletion", data: { userId } },
  ]);
  expect(mocks.process).not.toHaveBeenCalled();
});
